/* message.body.frame, present when the discriminant selects `kind.frame`.
 *
 * Reading another arm's bytes as this one's stays inside the view
 * and means nothing, so the accessor asks first and refuses. The
 * code is `default: error`'s, being the same mistake from the
 * other end. */
/** How many bytes `frame` occupies, for the switch
 * that places whatever follows the variant.
 */
static inline uint32_t fzn_call_message_body_frame_extent(situ_view_t view)
{
	situ_view_t whole;

	if (situ_view_sub(view, 11u, situ_remaining_u32(view.limit, 11u), &whole) != SITU_OK) {
		return 0u;
	}
	return fzn_call_frame_extent(whole);
}
static inline situ_err_t fzn_call_message_body_frame_view(situ_view_t view, situ_view_t *out)
{
	if (fzn_call_message_kind_get(view) != 5u) {
		return SITU_ERR_VERSION;
	}
	situ_view_t whole;

	if (situ_view_sub(view, 11u, situ_remaining_u32(view.limit, 11u), &whole) != SITU_OK) {
		return SITU_ERR_BOUNDS;
	}
	const uint32_t size = fzn_call_frame_extent(whole);
	return situ_view_sub(view, 11u, size, out);
}

#define FZN_CALL_MESSAGE_BODY_FRAME_PIECES_VALUE_MIN 1u

